'use strict';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=n=>state?.preferences?.hideMoney?'R$ ••••':(n/100).toLocaleString('pt-BR',{style:'currency',currency:'BRL'}),shortDate=s=>new Date(s+'T12:00').toLocaleDateString('pt-BR',{day:'numeric',month:'short'}),monthLabel=s=>new Date(s+'-01T12:00').toLocaleDateString('pt-BR',{month:'long',year:'numeric'});
const shapes={home:'M3 10 10 3l7 7v7h-5v-5H8v5H3z',task:'M5 3h10v14H5zM8 7h4M8 10h4M8 13h2',calendar:'M3 5h14v12H3zM6 3v4m8-4v4M3 9h14M6 12h1m3 0h1m3 0h1m-9 3h1m3 0h1',wallet:'M3 5h13v12H3zM3 5V3h10M12 9h6v5h-6zM15 11v1',more:'M3 10h1m5 0h1m5 0h1',clock:'M10 5a6 6 0 1 0 0 12 6 6 0 0 0 0-12zM10 8v4l2 1M8 2h4',gift:'M3 8h14v4H3zM5 12v6h10v-6M10 8v10M10 8H7a3 3 0 1 1 3-3v3zm0 0h3a3 3 0 1 0-3-3v3z',user:'M7 6a3 3 0 1 0 6 0 3 3 0 0 0-6 0zM3 18v-3l4-3h6l4 3v3z',check:'M4 10l4 4 8-9',box:'M4 4h12v12H4z',plus:'M10 4v12M4 10h12',edit:'m4 13 9-9 3 3-9 9H4zm7-7 3 3',search:'M8 3a5 5 0 1 0 0 10A5 5 0 0 0 8 3zm4 9 5 5',arrow:'m7 4 6 6-6 6',back:'m13 4-6 6 6 6',star:'m10 2 2 5 6 1-4 4 1 6-5-3-5 3 1-6-4-4 6-1z',leaf:'M5 15C1 4 9 3 17 3c0 9-4 14-12 12zm0 0 8-8',history:'M3 6v5h5M3 10a7 7 0 1 1 2 5M10 6v5l3 2',up:'M10 16V4M5 9l5-5 5 5',down:'M10 4v12M5 11l5 5 5-5',close:'m5 5 10 10M15 5 5 15',coin:'M6 2h8l4 4v8l-4 4H6l-4-4V6zM11 6H8v4h4v4H8',play:'m7 4 9 6-9 6z',pause:'M6 4v12M14 4v12',reset:'M4 8a7 7 0 1 1 1 7M3 3v6h6',download:'M10 2v11M6 9l4 4 4-4M3 14v4h14v-4'};
const icon=n=>`<svg class="icon" viewBox="0 0 20 20" aria-hidden="true"><path d="${shapes[n]||shapes.star}"/></svg>`;
const cats={luna:['Luna','Sonhadora'],mochi:['Mochi','Companheiro'],mikan:['Mikan','Curioso'],nori:['Nori','Aventureiro'],yuki:['Yuki','Tranquilo'],sora:['Sora','Criativo']};
const cat=(name=state.cat,cl='')=>`<img class="sprite ${cl}" src="assets/${Core.cats.includes(name)||name==='sleep'?name:'luna'}.svg" alt="Gatinho ${esc(cats[name]?.[0]||'dormindo')} em pixel art">`;
const categories=['Alimentação','Moradia','Transporte','Saúde','Estudos','Lazer','Compras','Outros'];
let state,loadError=false;try{const stored=localStorage.getItem('nekoquest_v4');if(stored)state=Core.validate(JSON.parse(stored));else{const old=localStorage.getItem('nekoquest_v3');if(old)state=Core.migrate(JSON.parse(old));else{let legacy=JSON.parse(localStorage.getItem('neko_tasks_v1')||'[]');state=Core.migrate({tasks:legacy})}}}catch{state=Core.defaults();loadError=true}
let page='home',taskFilter='today',query='',categoryFilter='all',sort='priority',calMonth=Core.today().slice(0,7),day=Core.today(),finMonth=Core.today().slice(0,7),finTab='overview',historyTab='all',installPrompt=null,financeFilter='all',financeQuery='',appUpdate=false;
function save(){if(loadError){toast('Importe um backup para retomar o salvamento. O arquivo anterior foi preservado.');return false}try{localStorage.setItem('nekoquest_v4',JSON.stringify(state));return true}catch{toast('Armazenamento indisponível. Exporte seu backup.');return false}}
function toast(text){$('#toast').textContent=text;$('#toast').hidden=false;clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').hidden=true,3500)}
const btn=(action,label,cl='')=>`<button class="${cl}" data-action="${action}">${label}</button>`;
const empty=(title,desc,skin='mochi')=>`<div class="empty">${cat(skin)}<h3>${title}</h3><p>${desc}</p></div>`;
const head=(k,title,desc='')=>`<div class="eyebrow">${k}</div><h1>${title}</h1>${desc?`<p class="muted">${desc}</p>`:''}`;
function go(p){page=p;render();window.scrollTo({top:0,behavior:'instant'});$('#app').focus({preventScroll:true})}
function modal(title,body){$('#modal').innerHTML=`<div class="row"><h2>${title}</h2><button class="quiet icon-btn" data-action="close" aria-label="Fechar">${icon('close')}</button></div>${body}`;$('#modal').showModal()}
function formField(label,name,value='',type='text',attrs=''){return `<div class="field"><label for="f-${name}">${label}</label><input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${attrs}></div>`}
function selectField(label,name,options,value){return `<div class="field"><label for="f-${name}">${label}</label><select id="f-${name}" name="${name}">${options.map(o=>{let [v,n]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${v===value?'selected':''}>${esc(n)}</option>`}).join('')}</select></div>`}
function monthSwitch(m,action){return `<div class="row card"><button class="quiet icon-btn" data-action="${action}" data-dir="-1" aria-label="Mês anterior">${icon('back')}</button><b>${monthLabel(m)}</b><button class="quiet icon-btn" data-action="${action}" data-dir="1" aria-label="Próximo mês">${icon('arrow')}</button></div>`}
function moveMonth(m,dir){let d=new Date(m+'-01T12:00');d.setMonth(d.getMonth()+dir);return Core.date(d).slice(0,7)}
function taskList(tasks){return tasks.length?tasks.map(t=>`<article class="task ${t.done?'done':''} ${t.priority==='high'?'important':''}"><button class="check" data-action="complete" data-id="${esc(t.id)}" aria-pressed="${t.done}" aria-label="${t.done?'Reabrir':'Concluir'} ${esc(t.title)}">${icon(t.done?'check':'box')}</button><button class="task-body grow" data-action="task-detail" data-id="${esc(t.id)}"><span class="title">${esc(t.title)}</span><small><span class="category-dot ${esc(['Estudos','Trabalho','Saúde','Pessoal'].includes(t.category)?t.category:'Pessoal')}"></span>${esc(t.category||'Pessoal')} · <span class="${!t.done&&t.date<Core.today()?'danger':''}">${t.date===Core.today()?'Hoje':shortDate(t.date)}${t.time?' · '+esc(t.time):''}</span></small>${t.subtasks.length?`<span class="mini-progress"><i style="width:${t.subtasks.filter(x=>x.done).length/t.subtasks.length*100}%"></i></span>`:''}</button><div class="task-end">${t.priority==='high'?'<span class="priority-mark" aria-label="Prioridade alta">!</span>':''}<small class="xp-tag">${esc(t.xp)} XP</small>${t.repeat!=='none'?'<small aria-label="Recorrente">↻</small>':''}</div></article>`).join(''):empty('Espaço para o próximo passo','Crie uma missão pequena. Seu gatinho acompanha você.')}

function home(){
 const dt=Core.today(),events=Core.completions(state),done=events.filter(h=>Core.date(new Date(h.at))===dt).length;
 const due=state.tasks.filter(t=>!t.done&&t.date<=dt).sort((a,b)=>Number(b.priority==='high')-Number(a.priority==='high')||a.date.localeCompare(b.date));
 const total=due.length+done,focusMinutes=state.sessions.filter(h=>Core.date(new Date(h.at))===dt).reduce((n,h)=>n+(h.minutes||0),0);
 return `<div class="row greeting"><div><div class="eyebrow">${new Date().toLocaleDateString('pt-BR',{weekday:'long',day:'numeric',month:'short'})}</div><h1>Olá, ${esc(state.name)} <span class="tiny-star">✦</span></h1></div><button class="level-pill" data-page="insights">Nv. ${1+Math.floor(state.xpTotal/100)}</button></div>
 <p class="intro muted">Seu dia, no seu ritmo.</p>
 <div class="scene scene-home"><div class="scene-copy"><span class="scene-kicker">SEU REFÚGIO</span><b>${esc(cats[state.cat][0])} está por aqui.</b><small>${due.length?'Vamos dar um pequeno passo?':'Uma pausa também faz parte.'}</small><button data-page="cats">Visitar os gatos ${icon('arrow')}</button></div>${cat(state.cat,'hero-cat')}<span class="firefly f1"></span><span class="firefly f2"></span></div>
 <div class="day-summary"><div class="row"><div><small>SEU DIA EM MOVIMENTO</small><p><b>${done}</b> de ${total} missões</p></div><div class="day-meter" style="--progress:${total?Math.round(done/total*100):0}%"><span>${total?Math.round(done/total*100):0}%</span></div></div><div class="summary-bottom"><span>${icon('clock')} ${focusMinutes} min de foco</span><span>${icon('coin')} ${state.coins} moedas</span></div></div>
 <div class="quick-actions"><button class="primary" data-action="task">${icon('plus')} Missão</button><button data-action="quick-expense">${icon('wallet')} Despesa</button><button data-page="focus">${icon('clock')} Focar</button></div>
 <div class="section row"><h2>Agora, um passo</h2><button class="quiet" data-page="tasks">Ver tudo ${icon('arrow')}</button></div>${taskList(due.slice(0,3))}
 <div class="section row"><h2>Sua semana</h2><button class="quiet" data-page="calendar">Abrir agenda ${icon('arrow')}</button></div>${weekStrip()}
 ${state.habits.length?`<div class="section row"><h2>Pequenos hábitos</h2><button class="quiet" data-page="habits">Ver todos ${icon('arrow')}</button></div>${state.habits.slice(0,2).map(habitCard).join('')}`:`<button class="habit-invite" data-action="habit">${cat('yuki','smallcat')}<span><b>Uma rotina mais leve</b><small>Crie seu primeiro hábito diário.</small></span>${icon('plus')}</button>`}`
}
function filteredTasks(){let ts=state.tasks.filter(t=>{if(taskFilter==='week'&&(t.date<Core.week(state)[0].day||t.date>Core.week(state)[6].day))return false;if(taskFilter==='today'&&(t.done||t.date>Core.today()))return false;if(taskFilter==='pending'&&t.done)return false;if(taskFilter==='done'&&!t.done)return false;if(taskFilter==='upcoming'&&(t.done||t.date<=Core.today()))return false;return t.title.toLocaleLowerCase().includes(query.toLocaleLowerCase())&&(categoryFilter==='all'||t.category===categoryFilter)});return ts.sort((a,b)=>sort==='priority'?(({high:2,normal:1,low:0}[b.priority]||0)-({high:2,normal:1,low:0}[a.priority]||0)||a.date.localeCompare(b.date)):a.date.localeCompare(b.date))}
function tasks(){return head('PLANNER','Missões','Organize o que importa para você.')+`<div class="search">${icon('search')}<input id="search" placeholder="Buscar missão…" aria-label="Buscar missão" value="${esc(query)}"></div><div class="chips">${[['today','Hoje e atrasadas'],['pending','A fazer'],['week','Esta semana'],['upcoming','Próximas'],['done','Concluídas'],['all','Todas']].map(([v,n])=>`<button data-action="task-filter" data-value="${v}" class="${v===taskFilter?'selected':''}">${n}</button>`).join('')}</div><div class="grid"><select id="categoryFilter" aria-label="Filtrar categoria"><option value="all">Todas as categorias</option>${['Estudos','Trabalho','Saúde','Pessoal'].map(c=>`<option ${categoryFilter===c?'selected':''}>${c}</option>`).join('')}</select><select id="taskSort" aria-label="Ordenar missões"><option value="date" ${sort==='date'?'selected':''}>Por data</option><option value="priority" ${sort==='priority'?'selected':''}>Por prioridade</option></select></div><div id="task-results">${taskGroups(filteredTasks())}</div>${btn('task',icon('plus')+' Nova missão','primary wide')}`}
function calendar(){let d=new Date(calMonth+'-01T12:00'),count=new Date(d.getFullYear(),d.getMonth()+1,0).getDate();return head('PLANEJE COM CALMA','Calendário')+monthSwitch(calMonth,'calendar-month')+`<div class="calendar">${['D','S','T','Q','Q','S','S'].map(c=>`<small>${c}</small>`).join('')}${'<span></span>'.repeat(d.getDay())}${Array.from({length:count},(_,i)=>{let dt=calMonth+'-'+String(i+1).padStart(2,'0');return `<button data-action="day" data-value="${dt}" class="${dt===day?'selected':''} ${state.tasks.some(t=>t.date===dt)?'dot':''}" aria-label="${shortDate(dt)}">${i+1}</button>`}).join('')}</div><div class="section row"><h2>${shortDate(day)}</h2><small>${state.tasks.filter(t=>t.date===day).length} missões</small></div>${taskList(state.tasks.filter(t=>t.date===day))}${btn('task',icon('plus')+' Missão neste dia','primary wide')}`}
function focus(){return head('RESPIRA. COMEÇA.','Hora do foco','Seu gatinho cuida da pausa. Você, do próximo passo.')+`<div class="timer">${cat('sleep')}<strong id="clock">25:00</strong><small>${state.timer.mode==='focus'?'FOCO':'PAUSA'}</small></div><div class="row">${btn('timer-reset',icon('reset'),'icon-btn')}${btn('timer',icon(state.timer.end?'pause':'play')+(state.timer.end?'Pausar':'Começar'),'primary grow')}${btn('timer-mode',state.timer.mode==='focus'?'Pausa':'Foco')}</div><div class="card"><label for="focusTask">Missão atual</label><select id="focusTask"><option value="">Foco livre</option>${state.tasks.filter(t=>!t.done).map(t=>`<option value="${esc(t.id)}" ${state.focusTask===t.id?'selected':''}>${esc(t.title)}</option>`).join('')}</select><form data-form="timer"><div class="grid">${formField('Foco (min)','focus',state.focus,'number','min="1" max="180" required')}${formField('Pausa (min)','break',state.break,'number','min="1" max="60" required')}</div><button class="wide">Salvar duração</button></form></div><p class="center muted">${state.sessions.length} sessões de foco concluídas</p>`}
function habitCard(h){let hit=h.days.includes(Core.today());return `<div class="card habit"><div class="row"><div class="grow"><b>${esc(h.title)}</b><small style="display:block">${h.days.length} dias registrados</small></div><button data-action="habit-check" data-id="${esc(h.id)}" class="${hit?'selected':''}" aria-label="${hit?'Desmarcar':'Marcar'} hábito de hoje">${icon(hit?'check':'box')}</button><button class="quiet icon-btn" data-action="habit" data-id="${esc(h.id)}" aria-label="Editar hábito">${icon('edit')}</button></div><div class="week">${Array.from({length:7},(_,i)=>{let dt=Core.addDays(Core.today(),i-6);return `<span class="${h.days.includes(dt)?'hit':''}" title="${shortDate(dt)}">${new Date(dt+'T12:00').toLocaleDateString('pt-BR',{weekday:'narrow'})}</span>`}).join('')}</div></div>`}
function habits(){return head('CONSISTÊNCIA GENTIL','Hábitos diários','Pequenas ações, um dia de cada vez.')+`<div class="center">${cat('yuki','bigcat')}</div>${state.habits.map(habitCard).join('')||empty('Sua rotina começa aqui','Escolha um hábito simples que cabe no seu dia.','yuki')}${btn('habit',icon('plus')+' Novo hábito','primary wide')}`}
function rewardPage(){return head('MERECIDAS PAUSAS','Recompensas')+`<div class="card row">${cat('mikan')}<div><small>Seu saldo de missões</small><h1 class="gold">${state.coins} ◈</h1><small>Moedas virtuais para suas pausas.</small></div></div><div class="grid">${state.rewards.map(r=>`<div class="card rewardcard"><div class="row">${cat(r.cat)}<button class="quiet icon-btn" data-action="reward" data-id="${esc(r.id)}" aria-label="Editar recompensa">${icon('edit')}</button></div><b>${esc(r.title)}</b><p class="gold">◈ ${r.cost}</p><button class="wide" data-action="redeem" data-id="${esc(r.id)}" ${state.coins<r.cost?'disabled':''}>Resgatar</button></div>`).join('')}</div>${btn('reward',icon('plus')+' Nova recompensa','primary wide')}<div class="section"><h2>Já aproveitadas</h2></div>${state.history.filter(h=>h.type==='reward').slice().reverse().slice(0,15).map(h=>`<div class="card row"><span>${esc(h.title)}</span><small>${new Date(h.at).toLocaleDateString('pt-BR')}</small></div>`).join('')||'<p class="muted">Suas pausas conquistadas aparecerão aqui.</p>'}`}
function entryList(entries){return entries.length?entries.slice().sort((a,b)=>b.date.localeCompare(a.date)).map(e=>`<article class="entry"><div class="entry-icon ${e.type==='income'?'positive':'danger'}">${icon(e.type==='income'?'down':'up')}</div><button class="entry-body grow" data-action="entry" data-id="${esc(e.id)}"><b>${esc(e.title)}</b><small>${esc(e.category)} · ${shortDate(e.date)}</small><small class="${!e.paid&&e.date<Core.today()?'danger':''}">${e.paid?'Efetivado':e.date<Core.today()?'Pendente · vencido':'Pendente'}</small></button><div class="entry-end"><b class="amount ${e.type==='income'?'positive':''}">${e.type==='income'?'+':'−'} ${money(e.amount)}</b>${!e.paid?`<button class="settle" data-action="settle" data-id="${esc(e.id)}">${e.type==='income'?'Receber':'Pagar'}</button>`:`<button class="quiet" data-action="entry" data-id="${esc(e.id)}" aria-label="Editar ${esc(e.title)}">${icon('edit')}</button>`}</div></article>`).join(''):empty('Seu mês começa aqui','Adicione uma receita ou despesa para acompanhar seus valores.','mikan')}

function finances(){let f=Core.finance(state,finMonth),budget=state.finance.budgets[finMonth]||{},totalBudget=Object.values(budget).reduce((a,b)=>a+b,0);let html=`<div class="row"><div>${head('UM FUTURO MAIS TRANQUILO','Finanças')}</div><button class="privacy-button icon-btn" data-action="privacy" aria-label="${state.preferences.hideMoney?'Mostrar valores':'Ocultar valores'}" aria-pressed="${state.preferences.hideMoney}">${state.preferences.hideMoney?'◌':'◉'}</button></div>`+monthSwitch(finMonth,'finance-month')+`<div class="tabs">${[['overview','Resumo'],['entries','Lançamentos'],['budget','Orçamento'],['goals','Metas']].map(([v,n])=>`<button class="${finTab===v?'selected':''}" data-action="finance-tab" data-value="${v}">${n}</button>`).join('')}</div>`;
if(finTab==='overview'){html+=`<div class="card finance-hero">${cat('mikan')}<small>Saldo acumulado</small><div class="money">${money(f.balance)}</div><div class="grid balance-grid"><div><small>↓ Recebido no mês</small><b class="positive">${money(f.income)}</b></div><div><small>↑ Pago no mês</small><b>${money(f.expense)}</b></div></div></div><div class="grid"><div class="card"><small>A pagar neste mês</small><p><b class="danger">${money(f.pending)}</b></p></div><div class="card"><small>A receber neste mês</small><p><b class="positive">${money(f.pendingIncome)}</b></p></div></div><div class="row section"><h2>Seu orçamento</h2>${btn('budget','Ajustar','quiet')}</div><div class="card"><div class="row"><small>Despesas pagas + pendentes</small><b>${money(f.committed)}</b></div><div class="bar ${f.committed>totalBudget&&totalBudget?'over':''}"><i style="width:${totalBudget?Math.min(100,f.committed/totalBudget*100):0}%"></i></div><small>${totalBudget?`Orçamento definido: ${money(totalBudget)}`:'Defina limites por categoria para acompanhar o mês.'}</small></div>${spendingChart()}<div class="section row"><h2>Últimos lançamentos</h2>${btn('finance-entries','Ver todos','quiet')}</div>${entryList(f.entries.slice().sort((a,b)=>b.date.localeCompare(a.date)).slice(0,4))}`}
if(finTab==='entries'){html+=`<div class="search">${icon('search')}<input id="finance-search" aria-label="Buscar lançamento" placeholder="Buscar lançamento…" value="${esc(financeQuery)}"></div><div class="chips">${[['all','Todos'],['pending','Pendentes'],['expense','Despesas'],['income','Receitas']].map(([v,n])=>`<button data-action="finance-filter" data-value="${v}" class="${financeFilter===v?'selected':''}">${n}</button>`).join('')}</div><div id="finance-results">${entryList(filteredEntries(f.entries))}</div>`+`<button class="wide" data-action="repeat-entries">Trazer recorrentes do mês anterior</button><p class="footnote">Copia os lançamentos marcados como mensais para este mês, como pendentes e sem duplicar.</p>`}
if(finTab==='budget'){html+=`<div class="card row">${cat('mochi','smallcat')}<p class="muted">Inclui despesas pagas e pendentes do mês.</p></div>${categories.map(c=>{let spent=f.entries.filter(e=>e.type==='expense'&&e.category===c).reduce((a,e)=>a+e.amount,0),limit=budget[c]||0;return `<div class="card"><div class="row"><b>${c}</b><small>${money(spent)} ${limit?'/ '+money(limit):''}</small></div><div class="bar ${limit&&spent>limit?'over':''}"><i style="width:${limit?Math.min(100,spent/limit*100):0}%"></i></div><small class="${limit&&spent>limit?'danger':''}">${limit?(spent>limit?'Acima do limite em '+money(spent-limit):'Disponível: '+money(limit-spent)):'Sem limite definido'}</small></div>`}).join('')}${btn('budget','Editar orçamento do mês','primary wide')}`}
if(finTab==='goals'){html+=`<p class="muted">Acompanhe o dinheiro que você já separou para seus planos.</p>${state.finance.goals.map(g=>`<div class="card"><div class="row">${cat('sora','smallcat')}<div class="grow"><b>${esc(g.title)}</b><small style="display:block">${money(g.saved)} de ${money(g.target)}</small></div><button class="quiet icon-btn" data-action="goal" data-id="${esc(g.id)}" aria-label="Editar meta">${icon('edit')}</button></div><div class="bar"><i style="width:${Math.min(100,g.saved/g.target*100)}%"></i></div><small>${g.saved>=g.target?'Meta alcançada!':Math.round(g.saved/g.target*100)+'% do caminho'}</small></div>`).join('')||empty('Um sonho de cada vez','Crie uma meta e atualize o valor que já guardou.','sora')}${btn('goal',icon('plus')+' Nova meta','primary wide')}<p class="footnote">Metas são um acompanhamento separado; seus valores não alteram o saldo ou os lançamentos.</p>`}
if(['overview','entries'].includes(finTab))html+=btn('entry',icon('plus')+' Novo lançamento','primary wide');html+=`<div class="row section">${btn('opening','Saldo inicial','quiet')}${btn('export-csv',icon('download')+' CSV do mês','quiet')}</div>`;return html}
function history(){let items=[...state.history,...state.sessions.map(s=>({...s,type:'focus',title:s.title||'Sessão de foco'}))].filter(h=>historyTab==='all'||h.type===historyTab).sort((a,b)=>b.at-a.at);return head('SEUS PASSOS CONTAM','Histórico')+`<div class="tabs">${[['all','Todos'],['task','Missões'],['focus','Foco'],['reward','Resgates']].map(([v,n])=>`<button data-action="history-tab" data-value="${v}" class="${historyTab===v?'selected':''}">${n}</button>`).join('')}</div>${items.map(h=>`<div class="entry"><div class="entry-icon">${icon(h.type==='task'?'check':h.type==='focus'?'clock':h.type==='reward'?'gift':'reset')}</div><div class="grow"><b>${esc(h.title)}</b><small>${new Date(h.at).toLocaleString('pt-BR')}</small></div><small>${h.type==='task'?(h.reverted?'Revertida':'+'+esc(h.xp)+' XP'):h.type==='reopen'?'Reaberta':''}</small></div>`).join('')||empty('Sua história começa agora','Conclua uma missão ou uma sessão de foco.','luna')}`}
function collection(){return head('UM REFÚGIO SÓ SEU','Clube dos gatos','Pequenos companheiros. Grandes aventuras.')+`<div class="scene collection-scene"><div class="scene-label">${esc(cats[state.cat][0])} · ${esc(cats[state.cat][1])}</div>${cat(state.cat)}${cat(state.cat==='mochi'?'nori':'mochi','sidecat')}${cat(state.cat==='mikan'?'sora':'mikan','sidecat right')}</div><div class="cats-grid">${Object.entries(cats).map(([id,[name,desc]])=>`<button class="cat-choice ${state.cat===id?'selected':''}" data-action="cat" data-value="${id}" aria-pressed="${state.cat===id}"><span class="cat-stage">${cat(id)}</span><b>${name}</b><small>${desc}</small>${state.cat===id?'<span class="chosen">COMPANHEIRO</span>':'<span class="choose-label">Escolher</span>'}</button>`).join('')}</div><div class="section"><h2>O cenário do seu refúgio</h2></div><div class="scene-options">${[['garden','Noite tranquila'],['sunset','Fim de tarde'],['rain','Dia de chuva']].map(([id,title])=>`<button class="scene-option ${state.preferences.scene===id?'selected':''}" data-action="scene" data-value="${id}" aria-pressed="${state.preferences.scene===id}"><span style="background-image:url('assets/${id}.svg')"></span>${title}</button>`).join('')}</div>`}

function more(){return head('DO SEU JEITO','Seu universo')+`<div class="card row">${cat(state.cat)}<div class="grow"><h2>${esc(state.name)}</h2><p class="muted">Nível ${1+Math.floor(state.xpTotal/100)} · ${state.xpTotal} XP</p></div></div>${[['insights','star','Meu progresso'],['calendar','calendar','Calendário'],['focus','clock','Pomodoro'],['habits','leaf','Hábitos diários'],['rewards','gift','Recompensas'],['cats','star','Clube dos gatos'],['history','history','Histórico'],['profile','user','Perfil e aparência']].map(([p,i,n])=>`<button class="menu-item" data-page="${p}"><span class="row">${icon(i)}${n}</span>${icon('arrow')}</button>`).join('')}`}
function profile(){return head('SEUS GOSTOS, SEU ESTILO','Meu perfil')+`<div class="center">${cat(state.cat,'bigcat')}</div><form data-form="profile">${formField('Como quer ser chamado?','name',state.name,'text','required maxlength="40"')}${selectField('Tema','theme',[['dark','Noite · escuro'],['light','Dia · claro']],state.theme)}<label>Cor principal</label><div class="palette">${['#b49aff','#f0a4ba','#8bd7c0','#8fbde8','#efc579'].map(c=>`<button type="button" data-action="color" data-value="${c}" class="${state.color===c?'selected':''}" style="background:${c}" aria-label="Cor ${c}"></button>`).join('')}</div>${formField('Ou escolha sua cor','color',state.color,'color')}<label class="checklabel"><input type="checkbox" name="motion" ${state.preferences.motion?'checked':''}> Animações suaves</label><button class="primary wide">Salvar perfil</button></form><button class="menu-item" data-page="cats">Escolher gatinho ${icon('arrow')}</button><div class="section"><h2>Seus dados</h2></div>${btn('backup',icon('download')+' Exportar backup completo','wide')}<label for="import">Restaurar backup JSON</label><input id="import" type="file" accept="application/json,.json">${btn('install','Instalar NekoQuest','wide')}<p class="footnote">Seus dados ficam neste navegador. O backup inclui tarefas e finanças. Não há conexão com banco ou sincronização automática.</p>`}
function render(){document.querySelector('meta[name=theme-color]').setAttribute('content',state.theme==='light'?'#f6f4fa':'#101321');document.body.classList.toggle('light',state.theme==='light');document.body.classList.toggle('still',!state.preferences.motion);document.body.dataset.scene=state.preferences.scene;document.documentElement.style.setProperty('--accent',state.color);let hex=state.color.slice(1),rgb=[0,2,4].map(i=>parseInt(hex.slice(i,i+2),16)/255),lum=rgb.map(x=>x<=.04045?x/12.92:((x+.055)/1.055)**2.4).reduce((a,x,i)=>a+x*[.2126,.7152,.0722][i],0);document.documentElement.style.setProperty('--ink',lum>.18?'#070612':'#ffffff');let bg=state.theme==='light'?.89:.008,contrast=(Math.max(bg,lum)+.05)/(Math.min(bg,lum)+.05);document.documentElement.style.setProperty('--accent-text',contrast>=4.5?state.color:state.theme==='light'?'#684299':'#c8b7ff');$('#header').innerHTML=`<div class="brand">${cat('luna','smallcat')}NekoQuest</div><button data-page="profile" aria-label="Abrir perfil">${cat(state.cat,'smallcat')}</button>`;let group=['calendar','focus','habits','rewards','cats','history','profile','more','insights'].includes(page)?'more':page;$('#nav').innerHTML=[['home','home','Início'],['tasks','task','Missões'],['finance','wallet','Finanças'],['focus','clock','Foco'],['more','more','Mais']].map(([p,i,n])=>`<button data-page="${p}" class="${(page==='focus'?p==='focus':p===group)?'active':''}" ${page===p?'aria-current="page"':''}>${icon(i)}${n}</button>`).join('');$('#app').innerHTML=(appUpdate?'<div class="update-banner"><span>Uma atualização está pronta.</span><button data-action="update-app">Atualizar</button></div>':'')+({home,tasks,calendar,focus,habits,rewards:rewardPage,finance:finances,history,cats:collection,more,profile,insights}[page]||home)();tick()}
function taskForm(id){let t=state.tasks.find(t=>t.id===id)||{title:'',date:page==='calendar'?day:Core.today(),category:'Estudos',priority:'normal',minutes:25,xp:10,repeat:'none',notes:'',subtasks:[]};modal(id?'Editar missão':'Nova missão',`<form data-form="task" data-id="${esc(id||'')}">${formField('O que você quer fazer?','title',t.title,'text','required maxlength="100"')}${selectField('Categoria','category',['Estudos','Trabalho','Saúde','Pessoal'],t.category)}<div class="grid form-grid">${formField('Data','date',t.date,'date','required')}${selectField('Prioridade','priority',[['normal','Normal'],['high','Alta'],['low','Baixa']],t.priority)}</div><div class="grid">${formField('Duração (min)','minutes',t.minutes,'number','min="1" max="600" required')}${formField('XP / moedas','xp',t.xp,'number',`min="1" max="10000" required ${t.done?'readonly':''}`)}</div>${formField('Horário (opcional)','time',t.time||'','time')}${selectField('Repetição após concluir','repeat',[['none','Não repetir'],['daily','Diariamente'],['weekly','Semanalmente'],['monthly','Mensalmente']],t.repeat)}<label for="f-notes">Notas</label><textarea id="f-notes" name="notes" maxlength="2000">${esc(t.notes)}</textarea><label for="f-subtasks">Subtarefas · uma por linha</label><textarea id="f-subtasks" name="subtasks" maxlength="3000" placeholder="Separar material&#10;Revisar o conteúdo">${esc(t.subtasks.map(s=>s.title).join('\n'))}</textarea>${t.subtasks.length?'<div class="checklist">'+t.subtasks.map((s,i)=>`<div class="subtask"><button type="button" data-action="subtask" data-id="${esc(id)}" data-index="${i}" aria-label="Alternar subtarefa">${icon(s.done?'check':'box')}</button><span>${esc(s.title)}</span></div>`).join('')+'</div>':''}<button class="primary wide">Salvar missão</button>${id?`<button type="button" class="wide danger" data-action="delete-task" data-id="${esc(id)}">Excluir missão</button>`:''}</form>`)}
function rewardForm(id){let r=state.rewards.find(r=>r.id===id)||{title:'',cost:25,cat:'mochi'};modal(id?'Editar recompensa':'Nova recompensa',`<form data-form="reward" data-id="${esc(id||'')}">${formField('Sua pausa merecida','title',r.title,'text','required maxlength="100"')}${formField('Custo em moedas de missão','cost',r.cost,'number','required min="1" max="10000"')}${selectField('Gatinho','cat',Object.entries(cats).map(([k,v])=>[k,v[0]]),r.cat)}<button class="primary wide">Salvar recompensa</button>${id?`<button type="button" class="wide danger" data-action="delete-reward" data-id="${esc(id)}">Excluir recompensa</button>`:''}</form>`)}
function habitForm(id){let h=state.habits.find(h=>h.id===id)||{title:''};modal(id?'Editar hábito':'Novo hábito',`<form data-form="habit" data-id="${esc(id||'')}">${formField('Um hábito para todos os dias','title',h.title,'text','required maxlength="100"')}<p class="footnote">Marque uma vez por dia e acompanhe seus últimos sete dias.</p><button class="primary wide">Salvar hábito</button>${id?`<button type="button" class="wide danger" data-action="delete-habit" data-id="${esc(id)}">Excluir hábito</button>`:''}</form>`)}
function entryForm(id){let e=state.finance.entries.find(e=>e.id===id)||{title:'',type:'expense',amount:0,date:finMonth===Core.today().slice(0,7)?Core.today():finMonth+'-01',category:'Outros',paid:false,recurring:false};modal(id?'Editar lançamento':'Novo lançamento',`<form data-form="entry" data-id="${esc(id||'')}">${selectField('Tipo','type',[['expense','Despesa'],['income','Receita']],e.type)}${formField('Descrição','title',e.title,'text','required maxlength="100"')}${formField('Valor (R$)','amount',e.amount?(e.amount/100).toFixed(2).replace('.',','):'','text','inputmode="decimal" required placeholder="0,00"')}${formField('Data de recebimento / vencimento','date',e.date,'date','required')}${selectField('Categoria','category',e.type==='income'?['Salário','Renda extra','Outros']:categories,e.category)}<label class="checklabel"><input type="checkbox" name="paid" ${e.paid?'checked':''}> Já foi pago ou recebido</label><label class="checklabel"><input type="checkbox" name="recurring" ${e.recurring?'checked':''}> Repetir mensalmente</label><p class="footnote">Os recorrentes são trazidos pelo botão da aba Lançamentos, sempre como pendentes.</p><button class="primary wide">Salvar lançamento</button>${id?`<button type="button" class="wide danger" data-action="delete-entry" data-id="${esc(id)}">Excluir lançamento</button>`:''}</form>`)}
function budgetForm(){let b=state.finance.budgets[finMonth]||{};modal('Orçamento · '+monthLabel(finMonth),`<form data-form="budget"><p class="footnote">Limites para este mês. Deixe vazio para não definir limite.</p>${categories.map((c,i)=>formField(c,'budget'+i,b[c]?(b[c]/100).toFixed(2).replace('.',','):'','text','inputmode="decimal" placeholder="Sem limite"')).join('')}<button class="primary wide">Salvar orçamento</button></form>`)}
function goalForm(id){let g=state.finance.goals.find(g=>g.id===id)||{title:'',target:0,saved:0};modal(id?'Editar meta':'Nova meta',`<form data-form="goal" data-id="${esc(id||'')}">${formField('Qual é seu plano?','title',g.title,'text','required maxlength="100"')}${formField('Objetivo (R$)','target',g.target?(g.target/100).toFixed(2).replace('.',','):'','text','inputmode="decimal" required')}${formField('Total já guardado (R$)','saved',(g.saved/100).toFixed(2).replace('.',','),'text','inputmode="decimal" required')}<p class="footnote">Atualize o total acumulado. Não cria lançamento nem altera seu saldo.</p><button class="primary wide">Salvar meta</button>${id?`<button type="button" class="wide danger" data-action="delete-goal" data-id="${esc(id)}">Excluir meta</button>`:''}</form>`)}
function download(name,content,type){let url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function tick(){let t=state.timer,n=t.end?Math.max(0,Math.ceil((t.end-Date.now())/1000)):t.remaining;if($('#clock'))$('#clock').textContent=String(Math.floor(n/60)).padStart(2,'0')+':'+String(n%60).padStart(2,'0');if(t.end&&n===0){if(t.mode==='focus')state.sessions.push({id:Core.id(),at:t.end,title:state.tasks.find(x=>x.id===state.focusTask)?.title||'Foco livre',minutes:state.focus});let wasFocus=t.mode==='focus';t.end=null;t.mode=wasFocus?'break':'focus';t.remaining=state[t.mode]*60;save();render();toast(wasFocus?'Foco concluído. Uma pausa para você!':'Pausa concluída. Pronto para continuar?')}}
function mutate(fn,message){fn();save();render();if(message)toast(message)}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;if(d.page){go(d.page);return}let a=d.action;if(!a)return;
if(a==='close')$('#modal').close();
if(a==='task')taskForm(d.id);if(a==='reward')rewardForm(d.id);if(a==='habit')habitForm(d.id);if(a==='entry')entryForm(d.id);if(a==='budget')budgetForm();if(a==='goal')goalForm(d.id);
if(a==='complete'){let done=Core.toggleTask(state,d.id);save();render();if(done){celebrate();toast('Missão concluída! XP e moedas conquistados.')}else toast('Missão reaberta. XP e moedas revertidos.')}
if(a==='subtask'){let t=state.tasks.find(t=>t.id===d.id),s=t.subtasks[+d.index];s.done=!s.done;save();b.innerHTML=icon(s.done?'check':'box')}
if(a.startsWith('delete-')){let type=a.slice(7),collections={task:state.tasks,reward:state.rewards,habit:state.habits,entry:state.finance.entries,goal:state.finance.goals};if(collections[type]&&confirm('Excluir este registro?')){let arr=collections[type],i=arr.findIndex(x=>x.id===d.id);if(i>=0)arr.splice(i,1);save();$('#modal').close();render();toast('Registro excluído.')}}
if(a==='task-filter'){taskFilter=d.value;render()}if(a==='day'){day=d.value;render()}if(a==='calendar-month'){calMonth=moveMonth(calMonth,+d.dir);day=calMonth+'-01';render()}if(a==='finance-month'){finMonth=moveMonth(finMonth,+d.dir);render()}if(a==='finance-tab'){finTab=d.value;render()}if(a==='finance-entries'){finTab='entries';render()}if(a==='history-tab'){historyTab=d.value;render()}
if(a==='habit-check')mutate(()=>{let h=state.habits.find(h=>h.id===d.id),dt=Core.today();h.days=h.days.includes(dt)?h.days.filter(x=>x!==dt):[...h.days,dt]});
if(a==='cat')mutate(()=>state.cat=d.value,'Novo companheiro escolhido!');
if(a==='redeem'){let r=state.rewards.find(r=>r.id===d.id);if(state.coins>=r.cost&&confirm(`Resgatar “${r.title}” por ${r.cost} moedas de missão?`))mutate(()=>{state.coins-=r.cost;state.history.push({id:Core.id(),type:'reward',title:r.title,cost:r.cost,at:Date.now()})},'Pausa conquistada. Aproveite!')}
if(a==='timer'){let t=state.timer;if(t.end){t.remaining=Math.max(0,Math.ceil((t.end-Date.now())/1000));t.end=null}else t.end=Date.now()+t.remaining*1000;save();render()}
if(a==='timer-reset'||a==='timer-mode'){let t=state.timer;t.end=null;if(a==='timer-mode')t.mode=t.mode==='focus'?'break':'focus';t.remaining=state[t.mode]*60;save();render()}
if(a==='color'){$('#f-color').value=d.value;document.querySelectorAll('.palette button').forEach(x=>x.classList.toggle('selected',x===b))}
if(a==='opening')modal('Saldo inicial',`<form data-form="opening">${formField('Saldo antes dos lançamentos (R$)','opening',(state.finance.opening/100).toFixed(2).replace('.',','),'text','inputmode="decimal" required')}<p class="footnote">Valor disponível antes do primeiro lançamento. É usado no saldo acumulado de todos os meses.</p><button class="primary wide">Salvar saldo inicial</button></form>`);
if(a==='repeat-entries'){let prev=moveMonth(finMonth,-1),count=0;state.finance.entries.filter(x=>x.date.startsWith(prev)&&x.recurring).forEach(x=>{let root=x.recurringId||x.id;if(!state.finance.entries.some(e=>e.date.startsWith(finMonth)&&(e.recurringId||e.id)===root)){state.finance.entries.push({...x,id:Core.id(),recurringId:root,date:Core.nextDate(x.date,'monthly',x.repeatDay||Number(x.date.slice(8))),repeatDay:x.repeatDay||Number(x.date.slice(8)),paid:false});count++}});save();render();toast(count?`${count} lançamento(s) recorrente(s) trazido(s).`:'Nenhum recorrente novo no mês anterior.')}
if(a==='backup')download('nekoquest-backup-'+Core.today()+'.json',JSON.stringify(state,null,2),'application/json');
if(a==='export-csv'){if(state.preferences.hideMoney&&!confirm('O CSV contém os valores completos. Exportar?'))return;let rows=[['Data','Descrição','Tipo','Categoria','Valor (R$)','Situação'],...Core.finance(state,finMonth).entries.map(e=>[e.date,e.title,e.type==='income'?'Receita':'Despesa',e.category,(e.amount/100).toFixed(2).replace('.',','),e.paid?'Efetivado':'Pendente'])];const cell=x=>'"'+String(x).replace(/^[=+@\-]/,"'$&").replace(/"/g,'""')+'"';download('nekoquest-financas-'+finMonth+'.csv','\ufeff'+rows.map(r=>r.map(cell).join(';')).join('\r\n'),'text/csv;charset=utf-8')}
if(a==='install'){if(installPrompt){await installPrompt.prompt();installPrompt=null}else modal('Leve seus gatos com você','<p>Abra o endereço HTTPS do app no navegador do celular.</p><p>No Android: menu do Chrome → Instalar app.</p><p>No iPhone: Compartilhar → Adicionar à Tela de Início.</p>')}
});
document.addEventListener('submit',e=>{let f=e.target,type=f.dataset.form;if(!type)return;e.preventDefault();let v=Object.fromEntries(new FormData(f)),id=f.dataset.id;try{
if(type==='task'){v.title=v.title.trim();if(!v.title||!Core.validDate(v.date))throw Error('Confira o título e a data.');let old=state.tasks.find(t=>t.id===id),lines=v.subtasks.split('\n').map(x=>x.trim()).filter(Boolean).slice(0,30);v.subtasks=lines.map((title,i)=>({title:title.slice(0,150),done:old?.subtasks[i]?.title===title?old.subtasks[i].done:false}));v.minutes=Number(v.minutes);v.xp=old?.done?old.xp:Number(v.xp);if(!Number.isInteger(v.xp)||v.xp<1||v.xp>10000||v.minutes<1||v.minutes>600)throw Error('Confira duração e XP.');if(old){if(old.date!==v.date)old.repeatDay=Number(v.date.slice(8));Object.assign(old,v)}else state.tasks.push({...v,id:Core.id(),done:false});}
if(type==='reward'){v.title=v.title.trim();v.cost=Number(v.cost);if(!v.title||!Number.isInteger(v.cost)||v.cost<1||v.cost>10000)throw Error('Confira os dados da recompensa.');if(id)Object.assign(state.rewards.find(r=>r.id===id),v);else state.rewards.push({...v,id:Core.id()})}
if(type==='habit'){v.title=v.title.trim();if(!v.title)throw Error('Dê um nome ao hábito.');if(id)state.habits.find(h=>h.id===id).title=v.title;else state.habits.push({id:Core.id(),title:v.title,days:[]})}
if(type==='entry'){v.title=v.title.trim();v.amount=Core.cents(v.amount);if(!v.title||v.amount<=0||!Core.validDate(v.date))throw Error('Confira descrição, valor e data.');if(v.type==='expense'&&!categories.includes(v.category))v.category='Outros';v.paid=v.paid==='on';v.recurring=v.recurring==='on';if(id){let old=state.finance.entries.find(x=>x.id===id);if(old.date!==v.date)old.repeatDay=Number(v.date.slice(8));Object.assign(old,v)}else state.finance.entries.push({...v,id:Core.id()});finMonth=v.date.slice(0,7)}
if(type==='budget'){let b={};categories.forEach((c,i)=>{if(v['budget'+i].trim()){let n=Core.cents(v['budget'+i]);if(n)b[c]=n}});state.finance.budgets[finMonth]=b}
if(type==='goal'){v.title=v.title.trim();v.target=Core.cents(v.target);v.saved=Core.cents(v.saved);if(!v.title||v.target===0)throw Error('Informe o nome e um objetivo maior que zero.');if(id)Object.assign(state.finance.goals.find(g=>g.id===id),v);else state.finance.goals.push({...v,id:Core.id()})}
if(type==='opening')state.finance.opening=Core.cents(v.opening);
if(type==='timer'){let focus=Number(v.focus),pause=Number(v.break);if(!Number.isInteger(focus)||!Number.isInteger(pause)||focus<1||focus>180||pause<1||pause>60)throw Error('Confira a duração.');if(state.timer.end)throw Error('Pause o timer antes de mudar a duração.');state.focus=focus;state.break=pause;state.timer.remaining=state[state.timer.mode]*60}
if(type==='profile'){state.name=v.name.trim()||'Aventureiro';state.theme=v.theme;state.color=v.color;state.preferences.motion=v.motion==='on'}
if(!save())return;$('#modal').close();render();toast('Salvo!');}catch(err){let existing=f.querySelector('.form-error');if(!existing){existing=document.createElement('p');existing.className='form-error';existing.setAttribute('role','alert');f.prepend(existing)}existing.textContent=err.message;existing.scrollIntoView({block:'nearest'});}});
document.addEventListener('input',e=>{if(e.target.id==='search'){query=e.target.value;$('#task-results').innerHTML=taskGroups(filteredTasks())}});
document.addEventListener('change',async e=>{if(e.target.id==='f-type'){let select=$('#f-category');if(select)select.innerHTML=(e.target.value==='income'?['Salário','Renda extra','Outros']:categories).map(c=>'<option>'+c+'</option>').join('')} if(e.target.id==='categoryFilter'){categoryFilter=e.target.value;$('#task-results').innerHTML=taskGroups(filteredTasks())}if(e.target.id==='taskSort'){sort=e.target.value;$('#task-results').innerHTML=taskGroups(filteredTasks())}if(e.target.id==='focusTask'){state.focusTask=e.target.value;save()}if(e.target.id==='import'&&e.target.files[0]){try{let file=e.target.files[0];if(file.size>10000000)throw Error('Backup muito grande.');let next=Core.validate(JSON.parse(await file.text()));if(confirm('Substituir seus dados atuais por este backup? Exporte o atual antes, se precisar.')){state=next;loadError=false;save();render();toast('Backup restaurado.')}}catch(err){toast('Backup não restaurado: '+err.message)}}});
function weekStrip(){return `<div class="week-strip">${Core.week(state).map(d=>`<button data-action="week-day" data-value="${d.day}" class="${d.day===Core.today()?'today':''}" aria-label="${shortDate(d.day)}, ${d.tasks} missões"><small>${new Date(d.day+'T12:00').toLocaleDateString('pt-BR',{weekday:'short'}).slice(0,3)}</small><b>${Number(d.day.slice(8))}</b><span class="day-dots">${d.tasks?'▪'.repeat(Math.min(3,d.tasks)):'·'}</span></button>`).join('')}</div>`}
function taskGroups(ts){if(!ts.length)return taskList(ts);let groups=[['Atrasadas',ts.filter(t=>!t.done&&t.date<Core.today())],['Hoje',ts.filter(t=>!t.done&&t.date===Core.today())],['Próximos dias',ts.filter(t=>!t.done&&t.date>Core.today())],['Concluídas',ts.filter(t=>t.done)]];return groups.filter(([,ts])=>ts.length).map(([title,ts])=>`<div class="task-group-title">${title}<span>${ts.length}</span></div>${taskList(ts)}`).join('')}
function filteredEntries(entries){return entries.filter(e=>(financeFilter==='all'||financeFilter==='pending'&&!e.paid||e.type===financeFilter)&&(e.title+' '+e.category).toLocaleLowerCase().includes(financeQuery.toLocaleLowerCase()))}
function spendingChart(){const rows=Core.spendByCategory(state,finMonth),total=rows.reduce((a,r)=>a+r.amount,0),palette=['#b49aff','#81cbb1','#e7a5b6','#e9c385','#80b4db','#b4b985','#c19bda','#c3ced4'];if(!rows.length)return '';return `<div class="section row"><h2>Para onde foi?</h2><small>Despesas pagas</small></div><div class="card spending"><div class="spending-track" role="img" aria-label="Distribuição de despesas pagas por categoria">${rows.map((r,i)=>`<i style="width:${r.amount/total*100}%;background:${palette[i%palette.length]}"></i>`).join('')}</div>${rows.map((r,i)=>`<div class="spending-row"><span><i style="background:${palette[i%palette.length]}"></i>${esc(r.category)}</span><small>${Math.round(r.amount/total*100)}%</small><b>${money(r.amount)}</b></div>`).join('')}</div>`}
function insights(){let week=Core.week(state),max=Math.max(1,...week.map(d=>d.count)),events=Core.completions(state),weekDone=week.reduce((a,d)=>a+d.count,0),focusMins=week.reduce((a,d)=>a+d.focus,0);return head('TODO PASSO CONTA','Meu progresso','Uma visão tranquila do que você construiu.')+`<div class="progress-profile">${cat(state.cat,'bigcat')}<div><span class="eyebrow">SEU COMPANHEIRO DE JORNADA</span><h2>Nível ${1+Math.floor(state.xpTotal/100)}</h2><p class="muted">${state.xpTotal} XP conquistados</p><progress value="${state.xpTotal%100}" max="100"></progress><small>${100-state.xpTotal%100} XP para o próximo nível</small></div></div><div class="grid"><div class="stat"><span class="stat-icon">${icon('check')}</span><div><strong>${weekDone}</strong><small>missões na semana</small></div></div><div class="stat"><span class="stat-icon">${icon('clock')}</span><div><strong>${focusMins}</strong><small>minutos de foco</small></div></div></div><div class="section"><h2>Uma semana de pequenos passos</h2></div><div class="card"><div class="activity-chart">${week.map(d=>`<div class="activity-column"><b>${d.count}</b><span><i style="height:${d.count/max*100}%"></i></span><small>${new Date(d.day+'T12:00').toLocaleDateString('pt-BR',{weekday:'narrow'})}</small></div>`).join('')}</div><small>Missões concluídas de segunda a domingo.</small></div><div class="section"><h2>Suas conquistas</h2></div><div class="achievement-list">${[[events.length>=1,'Primeiro passo','Concluir uma missão','check'],[events.length>=10,'Pegando o ritmo','Concluir 10 missões','star'],[state.sessions.length>=1,'Concentração felina','Terminar um Pomodoro','clock'],[state.habits.some(h=>h.days.length>=7),'Rotina com carinho','Registrar um hábito em 7 dias','leaf']].map(([unlocked,title,desc,i])=>`<div class="achievement ${unlocked?'unlocked':''}"><span>${icon(i)}</span><div class="grow"><b>${title}</b><small>${desc}</small></div><small>${unlocked?'✓':'○'}</small></div>`).join('')}</div><button class="wide" data-page="history">Ver histórico completo ${icon('arrow')}</button>`}
function taskDetail(id){let t=state.tasks.find(t=>t.id===id);if(!t)return;modal('Sua missão',`<div class="detail-top">${cat(state.cat,'smallcat')}<span class="badge">${esc(t.category||'Pessoal')}</span><span class="xp-tag">${esc(t.xp)} XP</span></div><h1 class="detail-title">${esc(t.title)}</h1><p class="muted">${shortDate(t.date)}${t.time?' às '+esc(t.time):''} · ${esc(t.minutes)} min${t.priority==='high'?' · Prioridade alta':''}</p>${t.notes?`<div class="detail-notes">${esc(t.notes)}</div>`:''}${t.subtasks.length?`<div class="section"><h2>Um passo de cada vez</h2></div><div class="detail-subtasks">${t.subtasks.map((s,i)=>`<button data-action="detail-subtask" data-id="${esc(t.id)}" data-index="${i}" aria-pressed="${s.done}">${icon(s.done?'check':'box')}<span>${esc(s.title)}</span></button>`).join('')}</div>`:''}<button class="primary wide" data-action="complete-detail" data-id="${esc(t.id)}">${icon(t.done?'reset':'check')}${t.done?'Reabrir missão':'Concluir missão'}</button><div class="grid detail-actions"><button data-action="task" data-id="${esc(t.id)}">${icon('edit')} Editar</button><button data-action="duplicate-task" data-id="${esc(t.id)}">${icon('plus')} Duplicar</button></div>${!t.done?`<button class="quiet wide" data-action="tomorrow" data-id="${esc(t.id)}">Deixar para amanhã</button>`:''}`)}
function celebrate(){if(!state.preferences.motion||window.matchMedia?.('(prefers-reduced-motion: reduce)').matches)return;let el=document.createElement('div');el.className='pixel-celebration';el.setAttribute('aria-hidden','true');el.innerHTML=Array.from({length:9},(_,i)=>`<i style="--x:${(i-4)*24}px;--r:${i*47}deg;--delay:${i*.02}s"></i>`).join('');document.body.append(el);setTimeout(()=>el.remove(),1400)}
document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;let d=b.dataset,a=d.action;
if(a==='week-day'){day=d.value;calMonth=day.slice(0,7);go('calendar')}
if(a==='task-detail')taskDetail(d.id);
if(a==='detail-subtask'){let t=state.tasks.find(t=>t.id===d.id),s=t.subtasks[+d.index];s.done=!s.done;save();b.setAttribute('aria-pressed',String(s.done));b.innerHTML=icon(s.done?'check':'box')+`<span>${esc(s.title)}</span>`;render()}
if(a==='complete-detail'){const done=Core.toggleTask(state,d.id);save();$('#modal').close();render();if(done)celebrate();toast(done?'Missão concluída. Um passo a mais!':'Missão reaberta.')}
if(a==='duplicate-task'){const t=state.tasks.find(t=>t.id===d.id),newTask={...t,id:Core.id(),done:false,nextId:null,completedAt:null,subtasks:t.subtasks.map(s=>({...s,done:false}))};state.tasks.push(newTask);save();render();taskForm(newTask.id)}
if(a==='tomorrow'){let t=state.tasks.find(t=>t.id===d.id);t.date=Core.addDays(Core.today(),1);t.repeatDay=Number(t.date.slice(8));save();$('#modal').close();render();toast('Missão movida para amanhã.')}
if(a==='privacy')mutate(()=>state.preferences.hideMoney=!state.preferences.hideMoney);
if(a==='scene')mutate(()=>state.preferences.scene=d.value,'Seu refúgio foi atualizado.');
if(a==='finance-filter'){financeFilter=d.value;render()}
if(a==='settle'){let item=state.finance.entries.find(x=>x.id===d.id);if(!item||item.paid)return;modal(item.type==='income'?'Confirmar recebimento':'Confirmar pagamento',`<p class="settle-description">${esc(item.title)}</p><div class="money">${money(item.amount)}</div><p class="muted">O lançamento será efetivado na data cadastrada: ${shortDate(item.date)}.</p><button class="primary wide" data-action="confirm-settle" data-id="${esc(item.id)}">Confirmar ${item.type==='income'?'recebimento':'pagamento'}</button><button class="quiet wide" data-action="entry" data-id="${esc(item.id)}">Alterar valor ou data</button>`)}
if(a==='confirm-settle'){let item=state.finance.entries.find(x=>x.id===d.id);if(item){item.paid=true;save();$('#modal').close();render();toast('Lançamento efetivado.')}}
if(a==='quick-expense'){entryForm();}
if(a==='update-app')location.reload();
});
document.addEventListener('input',e=>{if(e.target.id==='finance-search'){financeQuery=e.target.value;$('#finance-results').innerHTML=entryList(filteredEntries(Core.finance(state,finMonth).entries))}});

window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e});document.addEventListener('visibilitychange',()=>{if(!document.hidden)tick()});setInterval(tick,500);if('serviceWorker'in navigator&&location.protocol!=='file:'){const hadController=!!navigator.serviceWorker.controller;navigator.serviceWorker.addEventListener('controllerchange',()=>{if(hadController){appUpdate=true;render()}});navigator.serviceWorker.register('./service-worker.js').catch(()=>{});}render();if(loadError)toast('Não foi possível ler os dados salvos. O original foi preservado.');
